    if (Array.isArray(rot))
        return Number(rot[1] ?? 0);
    if (rot && typeof rot === "object")
        return Number(rot.y ?? 0);
    return 0;
}
async function pausaFisica(segundos = 0.06) {
    const w = world;
    if (typeof w.wait === "function") {
        await w.wait(segundos);
        return true;
    }
    const timer = globalThis.setTimeout;
    if (typeof timer === "function") {
        await new Promise((resolve) => timer(resolve, Math.max(15, Math.round(segundos * 1000))));
        return true;
    }
    return false;
}
function extrairIndiceAssento(textoId, label, fallback) {
    const matchLabel = String(label ?? "").match(/(\d+)/);
    if (matchLabel)
        return Number(matchLabel[1]);
    const matchId = String(textoId ?? "").match(/(\d+)/);
    if (matchId)
        return Number(matchId[1]) + 1;
    return fallback;
}
// Descobre as Hand Zones reais de cada assento lendo propriedades diretas, metadata e APIs de world
async function descobrirHandZonesDosAssentos() {
    const w = world;
    const todosObjetos = (await world.getAllObjects?.()) ?? [];
    const zonasApi = (await w.getZones?.()) ??
        (await w.getHandZones?.()) ??
        (await w.getPlayerZones?.()) ??
        [];
    const assentosApi = (await w.getSeats?.()) ?? [];
    const mapaSeats = new Map();
    for (let i = 0; i < assentosApi.length; i++) {
        const s = assentosApi[i];
        if (!s)
            continue;
        const sid = String(s.id ?? s.seatId ?? `seat-group-${i}`);
        const label = String(s.label ?? s.name ?? "");
        const color = String(s.color ?? "");
        mapaSeats.set(sid, {
            label,
            color,
            index: extrairIndiceAssento(sid, label, i + 1),
        });
    }
    // Reúne todas as zonas candidatas inspecionando também z.metadata
    const candidatosUnicos = new Map();
    for (const z of [...zonasApi, ...todosObjetos]) {
        if (!z || typeof z !== "object")
            continue;
        const meta = z.metadata ?? z.data ?? {};
        const kind = String(z.kind ?? z.type ?? z.zoneType ?? meta.kind ?? meta.type ?? meta.zoneType ?? "").toLowerCase();
        const nome = String(z.name ?? z.label ?? meta.name ?? meta.label ?? "").toLowerCase();
        const seatVinculado = z.seatId ??
            z.seatGroupId ??
            z.ownerSeat ??
            meta.seatId ??
            meta.seatGroupId ??
            meta.ownerSeat ??
            meta.assignedSeat;
        const ehZona = kind.includes("zone") ||
            kind === "hand" ||
            z.isHand === true ||
            z.isHandZone === true ||
            meta.isHand === true ||
            meta.isHandZone === true ||
            meta.hideFromOthers === true ||
            Boolean(seatVinculado) ||
            nome.includes("hand");
        if (ehZona && kind !== "card" && kind !== "deck") {
            const zid = String(z.id ?? `${nome}_${Math.random()}`);
            if (!candidatosUnicos.has(zid)) {
                candidatosUnicos.set(zid, z);
            }
        }
    }
    // Agrupa as zonas por assento
    const zonasPorAssento = new Map();
    for (const z of candidatosUnicos.values()) {
        const meta = z.metadata ?? z.data ?? {};
        const seatId = String(z.seatId ??
            z.seatGroupId ??
            z.ownerSeat ??
            z.seat ??
            meta.seatId ??
            meta.seatGroupId ??
            meta.ownerSeat ??
            meta.assignedSeat ??
            "");
        if (!seatId)
            continue;
        if (!zonasPorAssento.has(seatId)) {
            zonasPorAssento.set(seatId, []);
        }
        zonasPorAssento.get(seatId).push(z);
    }
    const handsEncontradas = [];
    for (const [seatId, listaZonas] of zonasPorAssento.entries()) {
        // Prioriza a zona marcada como Hand / Hide from other players
        let handEscolhida = listaZonas.find((z) => {
            const meta = z.metadata ?? z.data ?? {};
            const kind = String(z.kind ?? z.type ?? z.zoneType ?? meta.kind ?? meta.type ?? meta.zoneType ?? "").toLowerCase();
            const nome = String(z.name ?? z.label ?? meta.name ?? meta.label ?? "").toLowerCase();
            return (kind === "hand" ||
                z.isHand === true ||
                z.isHandZone === true ||
                z.hideFromOthers === true ||
                meta.isHand === true ||
                meta.hideFromOthers === true ||
                nome.includes("hand"));
        }) ?? null;
        // Se houver 2 zonas por assento (Hand + Play/Private), a Hand Zone é a mais próxima da borda externa
        if (!handEscolhida && listaZonas.length > 0) {
            handEscolhida = [...listaZonas].sort((a, b) => {
                const [ax, , az] = lerVetor(a.position);
                const [bx, , bz] = lerVetor(b.position);
                return Math.hypot(bx, bz) - Math.hypot(ax, az);
            })[0];
        }
        if (!handEscolhida)
            continue;
        const meta = handEscolhida.metadata ?? handEscolhida.data ?? {};
        const infoSeat = mapaSeats.get(seatId);
        const labelSeat = infoSeat?.label ||
            String(handEscolhida.seatLabel ??
                meta.seatLabel ??
                handEscolhida.label ??
                handEscolhida.name ??
                seatId);
        const seatIndex = infoSeat?.index ?? extrairIndiceAssento(seatId, labelSeat, 99);
        const centro = lerVetor(handEscolhida.position);
        const escala = lerVetor(handEscolhida.scale ?? handEscolhida.size ?? meta.scale ?? [0.9, 0.2, 0.45]);
        const rotacaoY = lerRotacaoY(handEscolhida.rotation);
        const meiaLargura = Math.max(0.32, Math.abs(escala[0]) * 0.5);
        const meiaProfundidade = Math.max(0.16, Math.abs(escala[2]) * 0.5);
        handsEncontradas.push({
            id: String(handEscolhida.id ?? seatId),
            seatId,
            seatIndex,
            nomeAssento: labelSeat || `Jogador ${seatIndex}`,
            centro,
            rotacaoY,
            meiaLargura,
            meiaProfundidade,
            instanciaZone: handEscolhida,
        });
    }
    // Ordena para pegar os Assentos 1, 2 e 3
    handsEncontradas.sort((a, b) => a.seatIndex - b.seatIndex);
    if (handsEncontradas.length === 0) {
        const metodosWorld = Object.keys(w).filter((k) => typeof w[k] === "function");
        estado.diagnosticoHands = `0 hands detectadas (objs=${todosObjetos.length}, zonasApi=${zonasApi.length}, seatsApi=${assentosApi.length}, worldFns=[${metodosWorld.join(",")}])`;
    }
    else {
        estado.diagnosticoHands = handsEncontradas
            .slice(0, 3)
            .map((h) => `${h.nomeAssento}[${h.seatId}]@(${h.centro[0].toFixed(2)},${h.centro[1].toFixed(2)},${h.centro[2].toFixed(2)})`)
            .join(" | ");
    }
    return handsEncontradas.slice(0, 3);
}
function encontrarSnapDisponivel(snapPoints, usados, coordenadaBase, nomeOpcional, raioMax = 0.3) {
    if (nomeOpcional) {
        const porNome = snapPoints.find((sp) => !usados.has(sp) &&
            String(sp?.name ?? "").trim().toLowerCase() === nomeOpcional.toLowerCase());
        if (porNome)
            return porNome;
    }
    const [bx, , bz] = coordenadaBase;
    let maisProximo = null;
    let menorDist = raioMax;
    for (const sp of snapPoints) {
        if (usados.has(sp))
            continue;
        const [sx, , sz] = lerVetor(sp.position ?? sp);
        const dist = Math.hypot(sx - bx, sz - bz);
        if (dist < menorDist) {
            menorDist = dist;
            maisProximo = sp;
        }
    }
    return maisProximo;
}
// Vincula automaticamente as zonas da mesa, os Snap Points de ataque e as Hand Zones dos assentos
async function sincronizarComSnapPoints() {
    const snapPoints = (await world.getSnapPoints?.()) ?? [];
    const usados = new Set();
    // 1. Vincula os 7 pontos centrais e o descarte
    for (const chave of Object.keys(POSICOES_BASE)) {
        const sp = encontrarSnapDisponivel(snapPoints, usados, POSICOES_BASE[chave], chave, 0.25);
        if (sp) {
            usados.add(sp);
            POSICOES_MESA[chave] = lerVetor(sp.position ?? sp);
        }
    }
    // 2. Vincula as Hand Zones reais dos Assentos 1, 2 e 3
    const handsReais = await descobrirHandZonesDosAssentos();
    estado.handsVinculadas = handsReais.length;
    for (let i = 0; i < JOGADORES_MESA.length; i++) {
        const jogador = JOGADORES_MESA[i];
        const hand = handsReais[i];
        if (hand) {
            jogador.nome = hand.nomeAssento || jogador.nome;
            jogador.seatId = hand.seatId;
            jogador.centroMao = hand.centro;
            jogador.rotacaoY = hand.rotacaoY;
            jogador.meiaLarguraMao = hand.meiaLargura;
            jogador.meiaProfundidadeMao = hand.meiaProfundidade;
            jogador.handZoneObj = hand.instanciaZone;
        }
    }
    // 3. Vincula os 3 Snap Points de ataque (por nome Ataque_1..3 ou proximidade com a Hand Zone)
    let vinculados = 0;
    for (const jogador of JOGADORES_MESA) {
        const referencia = estado.handsVinculadas > 0 ? jogador.centroMao : jogador.pontoAtaque;
        const spAtaque = encontrarSnapDisponivel(snapPoints, usados, referencia, jogador.nomeSnapAtaque, 5.0);
        if (spAtaque) {
            usados.add(spAtaque);
            jogador.pontoAtaque = lerVetor(spAtaque.position ?? spAtaque);
            vinculados++;
        }
    }
    estado.snapsAtaqueVinculados = vinculados;
}
async function listarTodosObjetos() {
    const objetos = await world.getAllObjects();
    return objetos ?? [];
}
async function obterObjetoPorNome(nome) {
    const todos = await listarTodosObjetos();
    return todos.find((obj) => obj?.name === nome) ?? null;
}
function dentroDaArea(posObj, centro, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO) {
    const [ox, , oz] = lerVetor(posObj);
    const [cx, , cz] = centro;
    return Math.abs(ox - cx) <= raioX && Math.abs(oz - cz) <= raioZ;
}
function dentroDaHandZone(obj, jogador) {
    if (!obj)
        return false;
    const meta = obj.metadata ?? {};
    const seatObj = String(obj.ownerSeat ?? obj.handSeatId ?? obj.seatId ?? meta.ownerSeat ?? meta.handSeatId ?? "");
    if (seatObj && seatObj === jogador.seatId) {
        return true;
    }
    const [ox, , oz] = lerVetor(obj.position);
    const [hx, , hz] = jogador.centroMao;
    const dx = ox - hx;
    const dz = oz - hz;
    const rad = (jogador.rotacaoY * Math.PI) / 180;
    const cos = Math.cos(rad);
    const sin = Math.sin(rad);
    const localX = dx * cos + dz * sin;
    const localZ = -dx * sin + dz * cos;
    return (Math.abs(localX) <= jogador.meiaLarguraMao + 0.08 &&
        Math.abs(localZ) <= jogador.meiaProfundidadeMao + 0.08);
}
// Verifica se a carta foi realmente solta (não está sendo segurada, suspensa no ar nem em movimento)
function estaCartaAssentada(obj, centro) {
    if (!obj)
        return false;
    if (obj.isHeld || obj.heldBy || obj.grabbedBy || obj.isDragging) {
        return false;
    }
    const [ox, oy, oz] = lerVetor(obj.position);
    const [, cy] = centro;
    const tetoMesa = Math.max(cy, ALTURA_MESA) + 0.08;
    if (oy > tetoMesa) {
        return false;
    }
    const chaveId = String(obj.id ?? "");
    if (chaveId) {
        const posAnt = estado.posicoesAnteriores.get(chaveId);
        if (!posAnt)
            return false;
        const deslocamento = Math.hypot(ox - posAnt[0], oy - posAnt[1], oz - posAnt[2]);
        if (deslocamento > 0.008) {
            return false;
        }
    }
    return true;
}
function atualizarHistoricoPosicoes(objetos) {
    const proximoMapa = new Map();
    for (const obj of objetos) {
        if (obj?.id) {
            proximoMapa.set(String(obj.id), lerVetor(obj.position));
        }
    }
    estado.posicoesAnteriores = proximoMapa;
}
async function objetosNaArea(centro, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO, apenasAssentadas = false) {
    const todos = await listarTodosObjetos();
    return todos.filter((obj) => obj &&
        obj.name !== "Deck_Ocorrencia" &&
        obj.name !== "Deck_Acao" &&
        String(obj.kind ?? "").toLowerCase() !== "zone" &&
        dentroDaArea(obj.position, centro, raioX, raioZ) &&
        (!apenasAssentadas || estaCartaAssentada(obj, centro)));
}
async function cartasNaArea(centro, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO, apenasAssentadas = false) {
    const objetos = await objetosNaArea(centro, raioX, raioZ, apenasAssentadas);
    return objetos.filter((obj) => (obj.stackCount ?? 1) <= 1);
}
function contarTotalCartas(objetos) {
    return objetos.reduce((soma, obj) => soma + Number(obj?.stackCount ?? 1), 0);
}
// Conta quantas cartas de Ação estão atualmente na mão real (Hand Zone) daquele jogador
async function contarCartasNaMaoDoJogador(jogador) {
    if (jogador.handZoneObj && typeof jogador.handZoneObj.getObjects === "function") {
        try {
            const objs = await jogador.handZoneObj.getObjects();
            if (Array.isArray(objs)) {
                return contarTotalCartas(objs);
            }
        }
        catch (_) { }
    }
    const todos = await listarTodosObjetos();
    const cartasNaHand = todos.filter((obj) => obj &&
        obj.name !== "Deck_Ocorrencia" &&
        obj.name !== "Deck_Acao" &&
        String(obj.kind ?? "").toLowerCase() !== "zone" &&
        !dentroDaArea(obj.position, jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO) &&
        dentroDaHandZone(obj, jogador));
    return contarTotalCartas(cartasNaHand);
}
async function moverCartaParaPonto(carta, destino, viradaParaCima, rotacaoY = 0, indicePilha = 0, usarAlturaExataDestino = false) {
    if (!carta || !destino)
        return;
    if (viradaParaCima && carta.faceUp === false && typeof carta.flip === "function") {
        await carta.flip();
        await pausaFisica(0.22);
    }
    else if (!viradaParaCima && carta.faceUp === true && typeof carta.flip === "function") {
        await carta.flip();
        await pausaFisica(0.22);
    }
    if (typeof carta.refresh === "function") {
        await carta.refresh();
    }
    if (typeof carta.setRotation === "function") {
        const rotAtual = Array.isArray(carta.rotation) ? carta.rotation : [0, rotacaoY, 0];
        const rx = Number(rotAtual[0] ?? 0);
        const rz = Number(rotAtual[2] ?? 0);
        const virouPeloEixoX = Math.abs(rx) > 90;
        const rzNormalizado = virouPeloEixoX ? (Math.abs(rz) > 90 ? 0 : 180) : rz;
        await carta.setRotation([0, rotacaoY, rzNormalizado]);
    }
    const yBase = usarAlturaExataDestino ? destino[1] : Math.max(destino[1], ALTURA_MESA);
    const ySeguro = Number((yBase + indicePilha * 0.015).toFixed(3));
    if (typeof carta.setPosition === "function") {
        await carta.setPosition([destino[0], ySeguro, destino[2]]);
    }
    if (typeof carta.refresh === "function") {
        await carta.refresh();
    }
    await pausaFisica(0.05);
}
// Envia a carta diretamente para dentro da Hand Zone do assento correspondente
async function enviarCartaParaMaoDoJogador(carta, jogador, indiceCartaNaMao) {
    if (!carta)
        return;
    // Calcula posição distribuída dentro do volume da Hand Zone
    const passoEspacamento = Math.min(0.12, (jogador.meiaLarguraMao * 1.4) / 2);
    const deslocamentoLateral = (indiceCartaNaMao - 1.5) * passoEspacamento;
    const rad = (jogador.rotacaoY * Math.PI) / 180;
    const yHand = jogador.centroMao[1] >= 1.45 ? jogador.centroMao[1] : ALTURA_MESA;
    const destinoMao = [
        Number((jogador.centroMao[0] + Math.cos(rad) * deslocamentoLateral).toFixed(3)),
        yHand,
        Number((jogador.centroMao[2] + Math.sin(rad) * deslocamentoLateral).toFixed(3)),
    ];
    // Tenta métodos nativos da Hand Zone / Carta caso existam na instância
    if (jogador.handZoneObj) {
        for (const metodo of ["addCard", "addObject", "insertCard", "dropCard"]) {
            if (typeof jogador.handZoneObj[metodo] === "function") {
                try {
                    await jogador.handZoneObj[metodo](carta);
                }
                catch (_) { }
            }
        }
    }
    for (const metodoCarta of ["moveToHand", "sendToHand", "dealToSeat", "setOwner"]) {
        if (typeof carta[metodoCarta] === "function") {
            try {
                await carta[metodoCarta](jogador.seatId);
            }
            catch (_) { }
        }
    }
    // Posiciona exatamente no centro/volume da Hand Zone para ativar a barra de mão do assento
    await moverCartaParaPonto(carta, destinoMao, true, jogador.rotacaoY, 0, true);
}
async function puxarCartaDoDeck(deck) {
    if (!deck)
        return null;
    if ((deck.stackCount ?? 0) <= 0)
        return null;
    let carta = null;
    if (typeof deck.drawCard === "function") {
        carta = await deck.drawCard();
    }
    else if (typeof deck.draw === "function") {
        const res = await deck.draw(1);
        carta = Array.isArray(res) ? res[0] : res;
    }
    if (carta && typeof carta.refresh === "function") {
        await carta.refresh();
    }
    return carta ?? null;
}
async function descompactarPilhas(objetos) {
    const individuais = [];
    for (const obj of objetos) {
        if (!obj)
            continue;
        while ((obj.stackCount ?? 1) > 1) {
            const extra = await puxarCartaDoDeck(obj);
            if (!extra)
                break;
            individuais.push(extra);
        }
        individuais.push(obj);
    }
    return individuais;
}
// ============================================================================
// 4. FLUXO DAS FASES (LOOP DA RODADA)
// ============================================================================
async function iniciarJogo() {
    if (estado.jogoIniciado)
        return;
    estado.jogoIniciado = true;
    estado.rodada = 1;
    estado.pontuacaoOculta = 0;
    await sincronizarComSnapPoints();
    const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
    const deckAcao = await obterObjetoPorNome("Deck_Acao");
    if (typeof deckOcorrencia?.shuffle === "function")
        await deckOcorrencia.shuffle();
    if (typeof deckAcao?.shuffle === "function")
        await deckAcao.shuffle();
    if (deckAcao) {
        estado.deckAcaoFaceUpBase = Boolean(deckAcao.faceUp);
    }
    await executarFase1();
    iniciarMonitoramentoContinuo();
}
// FASE 1: Garantir 3 cartas de ocorrência viradas para cima nos pontos configurados
async function executarFase1() {
    estado.faseAtual = "FASE_1";
    const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
    for (let i = 1; i <= 3; i++) {
        const pontoOcorrencia = POSICOES_MESA[`Ocorrencia_${i}`];
        const cartasAtuais = await objetosNaArea(pontoOcorrencia, RAIO_DETECCAO, RAIO_DETECCAO, false);
        if (cartasAtuais.length === 0) {
            const novaCarta = await puxarCartaDoDeck(deckOcorrencia);
            if (novaCarta) {
                await moverCartaParaPonto(novaCarta, pontoOcorrencia, true, 0, 0);
            }
        }
    }
    await executarFase2();
}
// FASE 2: Garantir que cada um dos 3 jogadores tenha 4 cartas de ação na sua Hand Zone
async function executarFase2() {
    estado.faseAtual = "FASE_2";
    const deckAcao = await obterObjetoPorNome("Deck_Acao");
    for (const jogador of JOGADORES_MESA) {
        let qtdNaMao = await contarCartasNaMaoDoJogador(jogador);
        while (qtdNaMao < 4) {
            // Se o deck tiver método nativo deal/dealToSeat, tenta primeiro; senão compra e envia para a Hand Zone
            let cartaAcao = null;
            if (deckAcao && typeof deckAcao.dealToSeat === "function") {
                try {
                    cartaAcao = await deckAcao.dealToSeat(jogador.seatId, 1);
                    if (Array.isArray(cartaAcao))
                        cartaAcao = cartaAcao[0];
                }
                catch (_) { }
            }
            if (!cartaAcao) {
                cartaAcao = await puxarCartaDoDeck(deckAcao);
                if (!cartaAcao)
                    break;
                await enviarCartaParaMaoDoJogador(cartaAcao, jogador, qtdNaMao);
            }
            qtdNaMao++;
        }
    }
    iniciarFase3();
}
// FASE 3: Cada jogador coloca 1 carta da sua mão no seu Snap Point de Ataque
function iniciarFase3() {
    estado.faseAtual = "FASE_3";
    estado.cartasAtaqueDaRodada.clear();
    estado.ultimoTotalSnapsPreenchidos = 0;
    world.broadcast(`Rodada ${estado.rodada} — Fase 3: Coloque 1 carta da sua mão em cada Snap Point de Ataque (${estado.handsVinculadas}/3 mãos: ${estado.diagnosticoHands}) e aperte F sobre o Deck_Acao para ir à Fase 4.`);
}
async function prepararCartasNosSnapPointsDeAtaque() {
    if (estado.faseAtual !== "FASE_3")
        return;
    let preenchidos = 0;
    for (const jogador of JOGADORES_MESA) {
        const cartas = await cartasNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, true);
        if (cartas.length === 1) {
            preenchidos++;
            if (cartas[0].faceUp === true && typeof cartas[0].flip === "function") {
                await cartas[0].flip();
                await pausaFisica(0.2);
            }
        }
    }
    if (preenchidos !== estado.ultimoTotalSnapsPreenchidos) {
        estado.ultimoTotalSnapsPreenchidos = preenchidos;
        if (preenchidos === 3) {
            world.broadcast("Snap Points de Ataque: 3/3 prontos! Aperte F sobre o Deck_Acao para revelar as cartas e ir para a Fase 4.");
        }
        else if (preenchidos > 0) {
            world.broadcast(`Snap Points de Ataque preenchidos: ${preenchidos}/3.`);
        }
    }
}
async function validarEAvancarParaFase4() {
    if (estado.faseAtual !== "FASE_3")
        return;
    const selecionadas = [];
    const pendentes = [];
    for (const jogador of JOGADORES_MESA) {
        const objetos = await objetosNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, true);
        const total = contarTotalCartas(objetos);
        if (total === 0) {
            pendentes.push(`${jogador.nome} (sem carta solta)`);
            continue;
        }
        if (total > 1) {
            pendentes.push(`${jogador.nome} (mais de 1 carta)`);
            continue;
        }
        selecionadas.push({ carta: objetos[0], jogador });
    }
    if (pendentes.length > 0) {
        world.broadcast(`Não foi possível avançar para a Fase 4. Verifique os Snap Points: ${pendentes.join(", ")}.`);
        return;
    }
    estado.cartasAtaqueDaRodada.clear();
    for (const { carta, jogador } of selecionadas) {
        await moverCartaParaPonto(carta, jogador.pontoAtaque, true, jogador.rotacaoY, 0);
        if (carta.id) {
            estado.cartasAtaqueDaRodada.add(String(carta.id));
        }
    }
    iniciarFase4();
}
// FASE 4: Jogadores movem livremente todas as cartas de Ataque para os 3 depósitos
function iniciarFase4() {
    estado.faseAtual = "FASE_4";
    world.broadcast("Fase 4: Cartas de Ataque reveladas! Aloquem todas elas nos 3 Depósitos à frente das Ocorrências.");
}
async function verificarConclusaoFase4() {
    if (estado.faseAtual !== "FASE_4")
        return;
    const totalEsperado = estado.cartasAtaqueDaRodada.size;
    if (totalEsperado === 0)
        return;
    for (const jogador of JOGADORES_MESA) {
        const sobras = await objetosNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, false);
        if (sobras.length > 0) {
            return;
        }
    }
    let totalDepositado = 0;
    for (let i = 1; i <= 3; i++) {
        const pontoDeposito = POSICOES_MESA[`Deposito_${i}`];
        const objetosNoDeposito = await objetosNaArea(pontoDeposito, RAIO_DETECCAO, RAIO_DETECCAO, true);
        totalDepositado += contarTotalCartas(objetosNoDeposito);
    }
    if (totalDepositado >= totalEsperado) {
        await executarFase5();
    }
}
// FASE 5: Resolver a ocorrência com mais cartas de ataque, descartar, pontuar e exibir debug
async function executarFase5() {
    estado.faseAtual = "FASE_5";
    let indiceVencedor = 1;
    let maiorQtdAtaques = -1;
    for (let i = 1; i <= 3; i++) {
        const pontoDeposito = POSICOES_MESA[`Deposito_${i}`];
        const objetos = await objetosNaArea(pontoDeposito, RAIO_DETECCAO, RAIO_DETECCAO, false);
        const qtdCartas = contarTotalCartas(objetos);
        if (qtdCartas > maiorQtdAtaques) {
            maiorQtdAtaques = qtdCartas;
            indiceVencedor = i;
        }
    }
    const pontoOcorrenciaVencedora = POSICOES_MESA[`Ocorrencia_${indiceVencedor}`];
    const pontoDepositoVencedor = POSICOES_MESA[`Deposito_${indiceVencedor}`];
    const pontoDescarte = POSICOES_MESA.Zona_Descarte;
    const objOcorrencia = await objetosNaArea(pontoOcorrenciaVencedora, RAIO_DETECCAO, RAIO_DETECCAO, false);
    const objAtaque = await objetosNaArea(pontoDepositoVencedor, RAIO_DETECCAO, RAIO_DETECCAO, false);
    const cartasOcorrencia = await descompactarPilhas(objOcorrencia);
    const cartasAtaque = await descompactarPilhas(objAtaque);
    const cartaOcorrenciaResolvida = cartasOcorrencia[0] ?? null;
    if (cartaOcorrenciaResolvida) {
        const resultado = await calcularPontuacao(cartaOcorrenciaResolvida, cartasAtaque);
        estado.pontuacaoOculta = Number((estado.pontuacaoOculta + resultado.pontos).toFixed(2));
        for (const linhaPasso of resultado.passosDebug) {
            world.broadcast(`[DEBUG R${estado.rodada}] ${linhaPasso}`);
        }
        world.broadcast(`[DEBUG R${estado.rodada}] Acumulado da partida: ${estado.pontuacaoOculta.toFixed(2)} pts`);
    }
    const objDescarte = await objetosNaArea(pontoDescarte, RAIO_DETECCAO, RAIO_DETECCAO, false);
    let qtdNoDescarte = contarTotalCartas(objDescarte);
    for (const carta of cartasOcorrencia) {
        await moverCartaParaPonto(carta, pontoDescarte, true, 0, qtdNoDescarte++);
    }
    for (const carta of cartasAtaque) {
        await moverCartaParaPonto(carta, pontoDescarte, true, 0, qtdNoDescarte++);
    }
    const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
    const restamNoDeck = (deckOcorrencia?.stackCount ?? 0) > 0;
    let restamNaMesa = false;
    for (let i = 1; i <= 3; i++) {
        const cartas = await objetosNaArea(POSICOES_MESA[`Ocorrencia_${i}`], RAIO_DETECCAO, RAIO_DETECCAO, false);
        if (cartas.length > 0) {
            restamNaMesa = true;
            break;
        }
    }
    if (restamNoDeck || restamNaMesa) {
        estado.rodada++;
        await executarFase1();
    }
    else {
        estado.faseAtual = "FIM_DE_JOGO";
        world.broadcast(`Fim de jogo! Todas as ocorrências foram resolvidas. Pontuação Final: ${estado.pontuacaoOculta.toFixed(2)} pts.`);
    }
}
function normalizarChaveAtributo(texto) {
    return texto
        .trim()
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/\s+/g, " ");
}
async function obterDadosCustomizadosDaCarta(carta) {
    const dadosMesclados = {};
    if (!carta || typeof carta !== "object")
        return dadosMesclados;
    const incorporar = (fonte) => {
        if (!fonte || typeof fonte !== "object" || Array.isArray(fonte))
            return;
        for (const [k, v] of Object.entries(fonte)) {
            const chaveNorm = String(k).trim().toLowerCase().replace(/\s+/g, "");
            if (chaveNorm && dadosMesclados[chaveNorm] === undefined && v !== undefined && v !== null) {
                dadosMesclados[chaveNorm] = v;
            }
        }
    };
    const metadataBase = carta.metadata ?? carta.data?.metadata;
    const cardIdDaInstancia = metadataBase?.cardId ?? carta.cardid ?? carta.name ?? carta.id;
    let achouNoSchema = false;
    const arrayCards = metadataBase?.customDeck?.cards;
    if (Array.isArray(arrayCards)) {
        const defCarta = arrayCards.find((c) => c.cardId === cardIdDaInstancia || c.label === carta.name);
        if (defCarta && defCarta.data) {
            incorporar(defCarta.data);
            achouNoSchema = true;
        }
    }
    if (!achouNoSchema) {
        incorporar(carta.data?.data);
        incorporar(carta.data);
        incorporar(carta.cardData);
        incorporar(carta);
    }
    return dadosMesclados;
}
async function extrairAtributosDaCarta(carta) {
    const atributos = {};
    const paresBrutos = [];
    if (!carta)
        return { atributos, paresBrutos };
    const dados = await obterDadosCustomizadosDaCarta(carta);
    for (let i = 1; i <= 3; i++) {
        const nomeRaw = dados[`atributo${i}`] ?? dados[`atributo_${i}`];
        const valorRaw = dados[`valor${i}`] ?? dados[`valor_${i}`];
        const rotulo = String(nomeRaw ?? "").trim();
        const rotuloLower = rotulo.toLowerCase();
        if (!rotulo ||
            rotuloLower === "null" ||
            rotuloLower === "undefined" ||
            rotuloLower === "nenhum" ||
            rotulo === "-") {
            continue;
        }
        const textoNumero = String(valorRaw ?? "0").trim().replace(",", ".");
        const valorNumerico = Number(textoNumero);
        if (Number.isNaN(valorNumerico) || !Number.isFinite(valorNumerico)) {
            paresBrutos.push(`slot${i}: ${rotulo} = inválido("${valorRaw}")`);
            continue;
        }
        paresBrutos.push(`slot${i}: ${rotulo}=${valorNumerico}`);
        const chaveAtributo = normalizarChaveAtributo(rotulo);
        if (!atributos[chaveAtributo]) {
            atributos[chaveAtributo] = { rotulo, valor: 0 };
        }
        atributos[chaveAtributo].valor += valorNumerico;
    }
    return { atributos, paresBrutos };
}
function formatarMapaAtributos(atr) {
    const entradas = Object.values(atr);
    if (entradas.length === 0)
        return "NENHUM";
    return entradas.map((item) => `${item.rotulo}=${item.valor}`).join(", ");
}
async function calcularPontuacao(cartaOcorrencia, cartasAtaque) {
    const passosDebug = [];
    const leituraOcorrencia = await extrairAtributosDaCarta(cartaOcorrencia);
    const textoAtrOcorrencia = formatarMapaAtributos(leituraOcorrencia.atributos);
    passosDebug.push(`Passo 1/5 (Ocorrência "${cartaOcorrencia?.name ?? "Sem nome"}"): [${textoAtrOcorrencia}] (${leituraOcorrencia.paresBrutos.join(", ") || "sem slots preenchidos"})`);
    const somaAcao = {};
    const resumoPorCartaAcao = [];
    for (let i = 0; i < cartasAtaque.length; i++) {
        const cartaAcao = cartasAtaque[i];
        const leituraAcao = await extrairAtributosDaCarta(cartaAcao);
        const textoAtr = formatarMapaAtributos(leituraAcao.atributos);
        resumoPorCartaAcao.push(`#${i + 1} "${cartaAcao?.name ?? "Ação"}" [${textoAtr}]`);
        for (const [chave, info] of Object.entries(leituraAcao.atributos)) {
            if (!somaAcao[chave]) {
                somaAcao[chave] = { rotulo: info.rotulo, valor: 0 };
            }
            somaAcao[chave].valor += info.valor;
        }
    }
    passosDebug.push(`Passo 2/5 (Cartas de Ação descartadas = ${cartasAtaque.length}): ${resumoPorCartaAcao.length > 0 ? resumoPorCartaAcao.join(" ; ") : "Nenhuma carta"}`);
    passosDebug.push(`Passo 3/5 (Soma dos atributos das Ações): [${formatarMapaAtributos(somaAcao)}]`);
    let totalRequerido = 0;
    let totalAtendido = 0;
    const comparacoes = [];
    for (const [chave, infoOcorrencia] of Object.entries(leituraOcorrencia.atributos)) {
        const requerido = Math.max(0, infoOcorrencia.valor);
        if (requerido <= 0)
            continue;
        const obtido = Math.max(0, somaAcao[chave]?.valor ?? 0);
        const atendido = Math.min(obtido, requerido);
        totalRequerido += requerido;
        totalAtendido += atendido;
        comparacoes.push(`${infoOcorrencia.rotulo}: Ações=${obtido} vs Ocorrência=${requerido} (válido=${atendido}/${requerido})`);
    }
    passosDebug.push(`Passo 4/5 (Comparação): ${comparacoes.length > 0 ? comparacoes.join(" | ") : "Sem atributos compatíveis detectados"}`);
    if (totalRequerido === 0) {
        passosDebug.push("Passo 5/5 (Resultado): Total exigido = 0 -> Nota = 0.00 / 10 pts");
        return { pontos: 0, percentual: 0, passosDebug };
    }
    const proporcao = Math.min(1, totalAtendido / totalRequerido);
    const percentual = Number((proporcao * 100).toFixed(2));
    const pontos = Number((proporcao * 10).toFixed(2));
    passosDebug.push(`Passo 5/5 (Resultado): Atendido ${totalAtendido} / Exigido ${totalRequerido} = ${percentual}% -> Nota: ${pontos.toFixed(2)} / 10 pts`);
    return {
        pontos,
        percentual,
        passosDebug,
    };
}
